import bisect

class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        maxleft = {}
        i = 0

        while i < n:
            diff = nums[i] - i
            if diff in maxleft:
                return max(maxleft.values())

            previdx = bisect.bisect_left(list(maxleft.keys()), diff)
            if previdx == 0:
                maxleft[diff] = nums[i]
            else:
                maxleft[diff] = max(maxleft[diff], maxleft[diff] + nums[i])

            nextidx = bisect.bisect_right(list(maxleft.keys()), diff)
            if nextidx < len(maxleft.keys()) and maxleft.peekitem(nextidx)[1] <= maxleft[diff]:
                del maxleft[maxleft.peekitem(nextidx)[0]]

            i += 1

        return max(maxleft.values())
